import numpy as np
from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import shortest_path

def n(v):
    v=np.array(v,dtype=float); return v/np.linalg.norm(v)
def perp(d):
    a=np.array([0,0,1.0])
    if abs(np.dot(a,n(d)))>0.9: a=np.array([1.0,0,0])
    return n(np.cross(d,a))
def rot(axis,ang):
    axis=n(axis); K=np.array([[0,-axis[2],axis[1]],[axis[2],0,-axis[0]],[-axis[1],axis[0],0]])
    return np.eye(3)+np.sin(ang)*K+(1-np.cos(ang))*K@K
def tet_from1(d, phi):
    ax=-n(d); p=perp(ax); th=np.deg2rad(70.53); out=[]
    for i in range(3):
        R=rot(ax, phi+2*np.pi*i/3.0)
        out.append(n(R@(np.cos(th)*ax+np.sin(th)*p)))
    return out
def tet_from2(d1,d2):
    d1,d2=n(d1),n(d2); b=-n(d1+d2); pp=n(np.cross(d1,d2)); h=np.deg2rad(54.75)
    return [n(np.cos(h)*b+np.sin(h)*pp), n(np.cos(h)*b-np.sin(h)*pp)]

class B:
    def __init__(s):
        s.els=[]; s.xyz=[]; s.bonds=[]
    def add(s,e,p,parent=None):
        s.els.append(e); s.xyz.append(np.array(p,float)); i=len(s.els)-1
        if parent is not None: s.bonds.append((parent,i))
        return i
    def methyl(s,ci,parent_pos,phi=0.0):
        cpos=s.xyz[ci]; d=n(cpos-parent_pos)
        for v in tet_from1(-d,phi): s.add('H',cpos+1.09*v,ci)
    def ch3(s,pi,direction,bond=1.52,phi=0.0):
        pp=s.xyz[pi]; c=pp+bond*n(direction); ci=s.add('C',c,pi); s.methyl(ci,pp,phi); return ci
    def aryl(s,pi,ipso_dir,nrm,methyls=(),bond=1.42):
        pp=s.xyz[pi]; d=n(ipso_dir); nn=n(nrm-np.dot(nrm,d)*d); e2=n(np.cross(nn,d))
        ipso=pp+bond*d; center=ipso+1.39*d; idx=[]
        for k in range(6):
            a=np.deg2rad(60*k)
            pos=center+1.39*(np.cos(a)*(-d)+np.sin(a)*e2)
            idx.append(s.add('C',pos, pi if k==0 else idx[k-1]))
        s.bonds.append((idx[0],idx[5]))
        for k in range(1,6):
            rad=n(s.xyz[idx[k]]-center)
            if k in methyls: s.ch3(idx[k],rad,bond=1.50)
            else: s.add('H',s.xyz[idx[k]]+1.08*rad, idx[k])
        return idx
    def ipr(s,pi,direction,phi,pbond=1.86):
        pp=s.xyz[pi]; d=n(direction); ci=s.add('C',pp+pbond*d,pi)
        ds=tet_from1(d,phi)
        s.add('H',s.xyz[ci]+1.09*ds[0],ci)
        s.ch3(ci,ds[1],bond=1.53); s.ch3(ci,ds[2],bond=1.53)
        return ci
    def write(s,fn,comment='mol'):
        with open(fn,'w') as f:
            f.write(f"{len(s.els)}\n{comment}\n")
            for e,x in zip(s.els,s.xyz): f.write(f"{e} {x[0]:.5f} {x[1]:.5f} {x[2]:.5f}\n")

def graph_dist(b):
    N=len(b.els)
    r=[];c=[]
    for i,j in b.bonds:
        r+= [i,j]; c+=[j,i]
    M=csr_matrix((np.ones(len(r)),(r,c)),shape=(N,N))
    return shortest_path(M,unweighted=True)

def clash(b, GD, cut=4):
    X=np.array(b.xyz); H=np.array([e=='H' for e in b.els])
    D=np.linalg.norm(X[:,None]-X[None],axis=-1); np.fill_diagonal(D,99)
    lim=np.where(H[:,None]&H[None,:],2.10,np.where(H[:,None]|H[None,:],2.50,3.00))
    m=GD>=cut
    v=np.where(m,np.clip(lim-D,0,None),0.0)
    md=D[m].min() if m.any() else 99
    return (v**2).sum(), md
